import {getLevel,chooseTopic} from './levels.js';
import {getLanguage} from './languages.js';
export const API='https://llm-api.arc.vt.edu/api/v1';
export const MODEL='gpt-oss-120b';
export const EMBEDDING_MODEL='Qwen3-Embedding-4B';
export function questionBody(recent=[],language='French',level='B1',topic=chooseTopic(level)){const spec=getLanguage(language);const learning=getLevel(level);if(!learning.topics.some(t=>t.name===topic.name&&t.details===topic.details))throw Error('Topic does not belong to the selected level.');return {model:MODEL,temperature:.8,top_p:1,reasoning_effort:'low',max_tokens:3072,stream:false,messages:[{role:'system',content:`Create one ${language}-to-English translation quiz for a ${level} ${language} learner. ${spec.instruction} Use this classroom level guidance: ${learning.guidance} Topic: ${topic.name}. Topic scope: ${topic.details} Invent a natural, self-contained sentence within this topic; do not require spaces in languages that do not use them. These are instructional targets, not certified CEFR judgments. For Ancient Greek and Latin, adapt modern scenarios to historically plausible equivalents within the topic, such as travel, messages, civic debate, trade, medicine, or contemporary-to-that-era innovations. For news or science use a hypothetical situation rather than inventing factual current events. Supply exactly four distinct, similarly sized English options: one faithful translation and three plausible distractors that materially change the meaning (such as agency, time, negation, or intention). Avoid obscure trivia, ambiguous source sentences, and two equally faithful translations. Vary everyday situations and sentence structures. Return ONLY valid JSON with exactly these keys: "source" (string), "options" (array of four English strings). Do not include answer labels, explanations, scores, or a correct-answer index. Do not favor any position. Scores will be calculated separately using embeddings.`},{role:'user',content:JSON.stringify({avoidRepeating:recent.slice(-12),task:'Create a fresh question.'})}]};}
export async function request(path,key,body,{signal,fetchImpl=fetch,timeout=180000}={}){
 const combined=signal?AbortSignal.any([signal,AbortSignal.timeout(timeout)]):AbortSignal.timeout(timeout);
 let response;try{response=await fetchImpl(`${API}/${path}`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${key}`},body:JSON.stringify(body),signal:combined,redirect:'error'});}catch{if(combined.aborted)throw Error(signal?.aborted?'Cancelled. Your score is unchanged.':'ARC timed out. Please try again.');throw Error('Cannot reach ARC. Check VT network/VPN access and whether ARC permits browser requests from this address (CORS).');}
 if(!response.ok)throw Error(({401:'ARC did not accept your key. Update it using ARC connection.',403:'ARC denied access. Check your account and model permissions.',429:'ARC is busy or rate-limiting requests. Wait a moment, then try again.'})[response.status]||`ARC returned HTTP ${response.status}. Please try again.`);
 return response.json();
}
export function parseQuestion(data){
 const choice=data?.choices?.[0];if(choice?.finish_reason!=='stop'||typeof choice.message?.content!=='string')throw Error('ARC did not finish the question. Please try again.');
 let q;try{q=JSON.parse(choice.message.content.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,''));}catch{throw Error('ARC returned an unreadable question. Please try again.');}
 if(!q||typeof q.source!=='string'||!q.source.trim()||q.source.length>1000||!Array.isArray(q.options)||q.options.length!==4||q.options.some(s=>typeof s!=='string'||!s.trim()||s.length>1500))throw Error('ARC returned an invalid question. Please try again.');
 const options=q.options.map(s=>s.trim());if(new Set(options.map(s=>s.normalize('NFKC').toLowerCase().replace(/[\p{P}\s]/gu,''))).size!==4)throw Error('ARC repeated an answer option. Please try again.');
 return {source:q.source.trim(),options};
}
export function shuffle(options,rng=Math.random){const out=[...options];for(let i=out.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[out[i],out[j]]=[out[j],out[i]];}return out;}
export function cosine(a,b){if(!Array.isArray(a)||!Array.isArray(b)||!a.length||a.length!==b.length||a.some(x=>!Number.isFinite(x))||b.some(x=>!Number.isFinite(x)))throw Error('ARC returned invalid embedding vectors.');let dot=0,aa=0,bb=0;for(let i=0;i<a.length;i++){dot+=a[i]*b[i];aa+=a[i]*a[i];bb+=b[i]*b[i];}if(!aa||!bb)throw Error('ARC returned a zero embedding vector.');return Math.max(-1,Math.min(1,dot/Math.sqrt(aa*bb)));}
export function scoreEmbeddings(data){if(!Array.isArray(data?.data)||data.data.length!==5)throw Error('ARC did not return all five embeddings.');const sorted=[...data.data].sort((a,b)=>a.index-b.index);if(sorted.some((v,i)=>v.index!==i))throw Error('ARC returned missing or duplicate embedding indices.');return sorted.slice(1).map(v=>cosine(sorted[0].embedding,v.embedding));}
export function winners(scores){if(scores.length!==4||scores.some(s=>!Number.isFinite(s)))throw Error('Invalid scores.');const max=Math.max(...scores);return scores.map((s,i)=>max-s<=1e-6?i:-1).filter(i=>i>=0);}
export function grade(question,selected){if(question.selected!==null)throw Error('This question has already been answered.');if(!Number.isInteger(selected)||selected<0||selected>3)throw Error('Choose one of the four options.');const best=winners(question.scores);return {...question,selected,correct:best.includes(selected),best};}
export async function makeQuestion(key,recent,{signal,fetchImpl=fetch,onStatus=()=>{},language='French',level='B1'}={}){getLanguage(language);getLevel(level);const topic=chooseTopic(level);onStatus(`Writing your next ${language} sentence…`);const q=parseQuestion(await request('chat/completions',key,questionBody(recent,language,level,topic),{signal,fetchImpl}));q.options=shuffle(q.options);if(signal?.aborted)throw Error('Cancelled. Your score is unchanged.');onStatus('Measuring all four translations with embeddings…');q.scores=scoreEmbeddings(await request('embeddings',key,{model:EMBEDDING_MODEL,input:[q.source,...q.options],encoding_format:'float'},{signal,fetchImpl}));if(signal?.aborted)throw Error('Cancelled. Your score is unchanged.');return {...q,language,level,topic:topic.name,selected:null};}
